"""seaborn._plotly_backend — plotly-backed axes-level plotters for CodeBench.

Real seaborn 0.13 drives matplotlib's artist internals (BarContainer
returns, transforms, sticky_edges, dpi_scale_trans, ...) that the
plotly-backed matplotlib shim doesn't emulate, so its plotters crash.
This module re-implements the axes-level plotting functions with the
OFFICIAL seaborn signatures (the common-keyword subset), rendering
through the same plotly pipeline the matplotlib shim uses. Everything
else in seaborn (palettes, themes, color utilities, load_dataset, ...)
stays the real upstream code.

Each function draws onto the current shim figure and returns
``plt.gca()`` — mirroring seaborn's "returns the matplotlib Axes"
contract.
"""

import numpy as np

__all__ = [
    'scatterplot', 'lineplot', 'barplot', 'countplot', 'histplot',
    'kdeplot', 'boxplot', 'violinplot', 'heatmap', 'regplot',
    'stripplot', 'swarmplot', 'pairplot', 'jointplot',
    'ecdfplot', 'pointplot', 'relplot', 'displot', 'catplot',
    'lmplot', 'clustermap',
]

_warned = set()


def _warn_once(key, msg):
    if key not in _warned:
        _warned.add(key)
        import sys
        print(f"[seaborn-plotly] {msg}", file=sys.__stderr__)


def _plt():
    from matplotlib import pyplot as p
    return p


def _go():
    import plotly.graph_objects as go
    return go


def _fig():
    return _plt()._ensure_fig()


def _resolve(data, v):
    """Resolve seaborn's data=/x= convention: v may be a column name,
    an array-like, or None."""
    if v is None:
        return None, None
    if isinstance(v, str) and data is not None:
        try:
            return np.asarray(data[v]), v
        except Exception:
            return None, v
    arr = np.asarray(v)
    name = getattr(v, 'name', None)
    return arr, (str(name) if name is not None else None)


def _palette_colors(palette, n):
    """n colors from a seaborn palette spec (falls back to plotly cycle)."""
    try:
        from seaborn.palettes import color_palette
        import matplotlib.colors as mcolors
        pal = color_palette(palette, n) if palette is not None else color_palette(n_colors=n)
        return [mcolors.to_hex(c) if not isinstance(c, str) else c for c in pal]
    except Exception:
        return [_plt()._next_color() for _ in range(n)]


def _groups(data, x_arr, y_arr, hue, hue_order=None):
    """Split (x, y) by hue. Yields (label, xg, yg) — single group if no hue."""
    if hue is None:
        yield None, x_arr, y_arr
        return
    h_arr, _ = _resolve(data, hue)
    if h_arr is None:
        yield None, x_arr, y_arr
        return
    levels = hue_order if hue_order is not None else list(dict.fromkeys(h_arr.tolist()))
    for lv in levels:
        m = h_arr == lv
        yield str(lv), (x_arr[m] if x_arr is not None else None), \
                       (y_arr[m] if y_arr is not None else None)


def _finish(xlabel=None, ylabel=None):
    p = _plt()
    if xlabel: p.xlabel(xlabel)
    if ylabel: p.ylabel(ylabel)
    return p.gca()


# ── relational ──────────────────────────────────────────────────────

def scatterplot(data=None, *, x=None, y=None, hue=None, size=None,
                style=None, palette=None, hue_order=None, alpha=None,
                s=None, color=None, label=None, legend='auto', ax=None, **kw):
    go = _go(); fig = _fig()
    x_arr, xl = _resolve(data, x)
    y_arr, yl = _resolve(data, y)
    s_arr, _ = _resolve(data, size)
    groups = list(_groups(data, x_arr, y_arr, hue, hue_order))
    colors = _palette_colors(palette, max(len(groups), 1))
    for i, (lv, xg, yg) in enumerate(groups):
        mk = dict(size=(_plt()._safe_float(s, 7) or 7),
                  color=(_plt()._color_to_str(color) if (color and len(groups) == 1) else colors[i % len(colors)]))
        if s_arr is not None and lv is None:
            sa = np.asarray(s_arr, float)
            rng = sa.max() - sa.min()
            mk['size'] = (4 + 14 * (sa - sa.min()) / (rng if rng else 1)).tolist()
        if alpha is not None:
            mk['opacity'] = float(alpha)
        xl_, yl_ = _plt()._to_list(xg), _plt()._to_list(yg)
        nm = (lv if lv is not None else (label or yl or 'points'))
        # Robust WebGL-or-SVG-decimated trace (never raises; handles iOS
        # plotly builds where Scattergl isn't usable).
        tr = _plt()._markers_trace(xl_, yl_, mk, name=nm)
        if tr is not None:
            tr.showlegend = bool(lv is not None or label)
            fig.add_trace(tr)
    return _finish(xl, yl)


def lineplot(data=None, *, x=None, y=None, hue=None, palette=None,
             hue_order=None, alpha=None, color=None, label=None,
             sort=True, linewidth=2, legend='auto', ax=None, **kw):
    go = _go(); fig = _fig()
    x_arr, xl = _resolve(data, x)
    y_arr, yl = _resolve(data, y)
    if x_arr is None and y_arr is not None:        # sns.lineplot(data=series)
        x_arr = np.arange(len(y_arr))
    groups = list(_groups(data, x_arr, y_arr, hue, hue_order))
    colors = _palette_colors(palette, max(len(groups), 1))
    for i, (lv, xg, yg) in enumerate(groups):
        if sort and xg is not None:
            o = np.argsort(np.asarray(xg, float), kind='stable')
            xg, yg = np.asarray(xg)[o], np.asarray(yg)[o]
            # seaborn aggregates duplicate x (mean) — do the same
            ux, inv = np.unique(np.asarray(xg, float), return_inverse=True)
            if len(ux) < len(xg):
                yag = np.zeros(len(ux)); cnt = np.zeros(len(ux))
                np.add.at(yag, inv, np.asarray(yg, float)); np.add.at(cnt, inv, 1)
                xg, yg = ux, yag / np.maximum(cnt, 1)
        line = dict(width=linewidth,
                    color=(_plt()._color_to_str(color) if (color and len(groups) == 1) else colors[i % len(colors)]))
        tr = go.Scatter(x=_plt()._to_list(xg), y=_plt()._to_list(yg), mode='lines',
                        line=line, name=(lv if lv is not None else (label or yl or '')),
                        showlegend=bool(lv is not None or label))
        if alpha is not None:
            tr.opacity = float(alpha)
        fig.add_trace(tr)
    return _finish(xl, yl)


# ── categorical ─────────────────────────────────────────────────────

def _cat_groups(data, x, y, hue, hue_order=None):
    """Return (cat_axis_label, value_label, orient, list[(hue_lv, cats, vals)]).
    orient 'v': categories on x, values on y."""
    x_arr, xl = _resolve(data, x)
    y_arr, yl = _resolve(data, y)
    # decide orientation: the non-numeric side is the categorical one
    def is_num(a):
        if a is None: return False
        try:
            np.asarray(a, dtype=float); return True
        except (TypeError, ValueError):
            return False
    if x_arr is not None and y_arr is not None:
        orient = 'v' if (is_num(y_arr) and not is_num(x_arr)) or (is_num(x_arr) and is_num(y_arr)) else 'h'
        cats, vals = (x_arr, y_arr) if orient == 'v' else (y_arr, x_arr)
        cl, vl = (xl, yl) if orient == 'v' else (yl, xl)
    elif x_arr is not None:
        orient, cats, vals, cl, vl = 'v', x_arr, None, xl, None
    else:
        orient, cats, vals, cl, vl = 'h', y_arr, None, yl, None
    out = []
    if hue is None:
        out.append((None, cats, vals))
    else:
        h_arr, _ = _resolve(data, hue)
        levels = hue_order if hue_order is not None else list(dict.fromkeys(h_arr.tolist()))
        for lv in levels:
            m = h_arr == lv
            out.append((str(lv), cats[m], (vals[m] if vals is not None else None)))
    return cl, vl, orient, out


def barplot(data=None, *, x=None, y=None, hue=None, palette=None,
            hue_order=None, estimator='mean', errorbar=None, color=None,
            alpha=None, ax=None, **kw):
    go = _go(); fig = _fig()
    est = {'mean': np.mean, 'median': np.median, 'sum': np.sum,
           'min': np.min, 'max': np.max}.get(estimator, estimator if callable(estimator) else np.mean)
    cl, vl, orient, groups = _cat_groups(data, x, y, hue, hue_order)
    colors = _palette_colors(palette, max(len(groups), 1))
    for i, (lv, cats, vals) in enumerate(groups):
        levels = list(dict.fromkeys(cats.tolist()))
        heights = [float(est(np.asarray(vals)[cats == c].astype(float))) for c in levels] \
            if vals is not None else [float(np.sum(cats == c)) for c in levels]
        bar_kw = dict(name=(lv or vl or ''), showlegend=lv is not None,
                      marker_color=(_plt()._color_to_str(color) if (color and len(groups) == 1) else colors[i % len(colors)]))
        if alpha is not None: bar_kw['opacity'] = float(alpha)
        if orient == 'v':
            fig.add_trace(go.Bar(x=[str(c) for c in levels], y=heights, **bar_kw))
        else:
            fig.add_trace(go.Bar(y=[str(c) for c in levels], x=heights, orientation='h', **bar_kw))
    if len(groups) > 1:
        try: fig.update_layout(barmode='group')
        except Exception: pass
    return _finish(cl if orient == 'v' else vl, vl if orient == 'v' else cl)


def countplot(data=None, *, x=None, y=None, hue=None, palette=None,
              hue_order=None, color=None, ax=None, **kw):
    return barplot(data=data, x=x, y=y, hue=hue, palette=palette,
                   hue_order=hue_order, color=color, ax=ax, **kw)


def boxplot(data=None, *, x=None, y=None, hue=None, palette=None,
            hue_order=None, color=None, ax=None, **kw):
    go = _go(); fig = _fig()
    cl, vl, orient, groups = _cat_groups(data, x, y, hue, hue_order)
    colors = _palette_colors(palette, max(len(groups), 1))
    for i, (lv, cats, vals) in enumerate(groups):
        series = vals if vals is not None else cats
        cat_ax = [str(c) for c in cats] if vals is not None else None
        bk = dict(name=(lv or vl or ''), showlegend=lv is not None,
                  marker_color=(_plt()._color_to_str(color) if (color and len(groups) == 1) else colors[i % len(colors)]))
        if orient == 'v':
            fig.add_trace(go.Box(x=cat_ax, y=_plt()._to_list(series), **bk))
        else:
            fig.add_trace(go.Box(y=cat_ax, x=_plt()._to_list(series), orientation='h', **bk))
    if len(groups) > 1:
        try: fig.update_layout(boxmode='group')
        except Exception: pass
    return _finish(cl if orient == 'v' else vl, vl if orient == 'v' else cl)


def violinplot(data=None, *, x=None, y=None, hue=None, palette=None,
               hue_order=None, color=None, ax=None, **kw):
    go = _go(); fig = _fig()
    cl, vl, orient, groups = _cat_groups(data, x, y, hue, hue_order)
    colors = _palette_colors(palette, max(len(groups), 1))
    for i, (lv, cats, vals) in enumerate(groups):
        series = vals if vals is not None else cats
        cat_ax = [str(c) for c in cats] if vals is not None else None
        vk = dict(name=(lv or vl or ''), showlegend=lv is not None, box_visible=True,
                  marker_color=(_plt()._color_to_str(color) if (color and len(groups) == 1) else colors[i % len(colors)]))
        if orient == 'v':
            fig.add_trace(go.Violin(x=cat_ax, y=_plt()._to_list(series), **vk))
        else:
            fig.add_trace(go.Violin(y=cat_ax, x=_plt()._to_list(series), orientation='h', **vk))
    if len(groups) > 1:
        try: fig.update_layout(violinmode='group')
        except Exception: pass
    return _finish(cl if orient == 'v' else vl, vl if orient == 'v' else cl)


def stripplot(data=None, *, x=None, y=None, hue=None, palette=None,
              hue_order=None, jitter=True, color=None, alpha=None, ax=None, **kw):
    go = _go(); fig = _fig()
    cl, vl, orient, groups = _cat_groups(data, x, y, hue, hue_order)
    colors = _palette_colors(palette, max(len(groups), 1))
    rng = np.random.RandomState(0)
    for i, (lv, cats, vals) in enumerate(groups):
        series = vals if vals is not None else cats
        cat_ax = [str(c) for c in cats] if vals is not None else ['0'] * len(series)
        mk = dict(size=5, color=(_plt()._color_to_str(color) if (color and len(groups) == 1) else colors[i % len(colors)]))
        if alpha is not None: mk['opacity'] = float(alpha)
        bx = go.Box(x=cat_ax if orient == 'v' else _plt()._to_list(series),
                    y=_plt()._to_list(series) if orient == 'v' else cat_ax,
                    boxpoints='all', jitter=(0.4 if jitter else 0), pointpos=0,
                    fillcolor='rgba(0,0,0,0)', line=dict(color='rgba(0,0,0,0)'),
                    marker=mk, name=(lv or vl or ''), showlegend=lv is not None)
        fig.add_trace(bx)
    return _finish(cl if orient == 'v' else vl, vl if orient == 'v' else cl)


def swarmplot(*a, **kw):
    return stripplot(*a, **kw)


# ── distributions ───────────────────────────────────────────────────

def histplot(data=None, *, x=None, y=None, bins='auto', binwidth=None,
             stat='count', hue=None, palette=None, hue_order=None, kde=False,
             color=None, alpha=None, label=None, element='bars', ax=None, **kw):
    go = _go(); fig = _fig()
    # sns.histplot(series) / histplot(data=df, x='col') / histplot(x=arr)
    if x is None and y is None and data is not None and not hasattr(data, 'columns'):
        x = np.asarray(data); data = None
    x_arr, xl = _resolve(data, x)
    y_arr, yl = _resolve(data, y)
    arr, lab, horizontal = (x_arr, xl, False) if x_arr is not None else (y_arr, yl, True)
    if arr is None:
        return _plt().gca()
    groups = list(_groups(data, arr, None, hue, hue_order))
    colors = _palette_colors(palette, max(len(groups), 1))
    histnorm = {'count': None, 'density': 'probability density',
                'probability': 'probability', 'percent': 'percent'}.get(stat)
    for i, (lv, ag, _unused) in enumerate(groups):
        ag = np.asarray(ag, float)
        hk = dict(name=(lv or label or lab or ''), showlegend=bool(lv or label),
                  marker_color=(_plt()._color_to_str(color) if (color and len(groups) == 1) else colors[i % len(colors)]),
                  opacity=(float(alpha) if alpha is not None else 0.8))
        if histnorm: hk['histnorm'] = histnorm
        if binwidth is not None:
            start = float(np.min(ag))
            hk['xbins' if not horizontal else 'ybins'] = dict(start=start, size=float(binwidth))
        elif isinstance(bins, (int, np.integer)):
            hk['nbinsx' if not horizontal else 'nbinsy'] = int(bins)
        elif _plt()._has_len(bins):
            edges = np.asarray(bins, float)
            hk['xbins' if not horizontal else 'ybins'] = dict(
                start=float(edges[0]), end=float(edges[-1]),
                size=float(edges[1] - edges[0]) if len(edges) > 1 else None)
        fig.add_trace(go.Histogram(**({'x': _plt()._to_list(ag)} if not horizontal else {'y': _plt()._to_list(ag)}), **hk))
        if kde:
            gx, gy = _gaussian_kde(ag)
            if histnorm is None:                       # scale KDE to counts
                n = len(ag)
                bw = (np.max(ag) - np.min(ag)) / (int(bins) if isinstance(bins, (int, np.integer)) else 10)
                gy = gy * n * (bw if bw > 0 else 1)
            fig.add_trace(go.Scatter(x=(gx if not horizontal else gy), y=(gy if not horizontal else gx),
                                     mode='lines', name=f"{lv or lab or 'kde'} kde",
                                     line=dict(color=hk['marker_color']), showlegend=False))
    if len(groups) > 1:
        try: fig.update_layout(barmode='overlay')
        except Exception: pass
    return _finish(lab if not horizontal else 'Count', 'Count' if not horizontal else lab)


def _gaussian_kde(arr, gridsize=200):
    """numpy-only gaussian KDE (Scott's rule), like seaborn's default."""
    arr = np.asarray(arr, float)
    arr = arr[np.isfinite(arr)]
    n = len(arr)
    if n < 2:
        return np.array([0.0]), np.array([0.0])
    std = arr.std(ddof=1)
    bw = std * n ** (-1.0 / 5.0) if std > 0 else 1.0
    lo, hi = arr.min() - 3 * bw, arr.max() + 3 * bw
    grid = np.linspace(lo, hi, gridsize)
    diff = (grid[:, None] - arr[None, :]) / bw
    dens = np.exp(-0.5 * diff ** 2).sum(axis=1) / (n * bw * np.sqrt(2 * np.pi))
    return grid, dens


def kdeplot(data=None, *, x=None, y=None, hue=None, palette=None,
            hue_order=None, fill=False, color=None, alpha=None,
            label=None, bw_adjust=1.0, ax=None, **kw):
    go = _go(); fig = _fig()
    if x is None and y is None and data is not None and not hasattr(data, 'columns'):
        x = np.asarray(data); data = None
    x_arr, xl = _resolve(data, x)
    if x_arr is None:
        return _plt().gca()
    groups = list(_groups(data, x_arr, None, hue, hue_order))
    colors = _palette_colors(palette, max(len(groups), 1))
    for i, (lv, ag, _unused) in enumerate(groups):
        gx, gy = _gaussian_kde(np.asarray(ag, float))
        if bw_adjust != 1.0:    # re-evaluate with adjusted bandwidth
            arr = np.asarray(ag, float); arr = arr[np.isfinite(arr)]
            n = len(arr); std = arr.std(ddof=1)
            bw = (std * n ** (-0.2) if std > 0 else 1.0) * float(bw_adjust)
            gx = np.linspace(arr.min() - 3 * bw, arr.max() + 3 * bw, 200)
            diff = (gx[:, None] - arr[None, :]) / bw
            gy = np.exp(-0.5 * diff ** 2).sum(axis=1) / (n * bw * np.sqrt(2 * np.pi))
        c = (_plt()._color_to_str(color) if (color and len(groups) == 1) else colors[i % len(colors)])
        tr = go.Scatter(x=gx.tolist(), y=gy.tolist(), mode='lines',
                        line=dict(color=c), name=(lv or label or xl or 'density'),
                        showlegend=bool(lv or label),
                        fill=('tozeroy' if fill else None))
        if alpha is not None: tr.opacity = float(alpha)
        fig.add_trace(tr)
    return _finish(xl, 'Density')


# ── matrix ──────────────────────────────────────────────────────────

def heatmap(data, *, vmin=None, vmax=None, cmap=None, center=None,
            annot=None, fmt='.2g', linewidths=0, linecolor='white',
            cbar=True, square=False, xticklabels='auto', yticklabels='auto',
            mask=None, ax=None, **kw):
    go = _go(); fig = _fig()
    try:
        import pandas as pd
        is_df = isinstance(data, pd.DataFrame)
    except Exception:
        is_df = False
    z = np.asarray(data, dtype=float)
    xt = list(data.columns.astype(str)) if is_df else list(range(z.shape[1]))
    yt = list(data.index.astype(str)) if is_df else list(range(z.shape[0]))
    if mask is not None:
        z = np.where(np.asarray(mask, bool), np.nan, z)
    from matplotlib.cm import to_plotly
    scale = to_plotly(cmap) if cmap is not None else 'rdbu_r' if center is not None else 'viridis'
    hk = dict(z=z.tolist(), x=xt, y=yt, colorscale=scale, showscale=bool(cbar))
    if vmin is not None: hk['zmin'] = float(vmin)
    if vmax is not None: hk['zmax'] = float(vmax)
    if center is not None: hk['zmid'] = float(center)
    if annot:
        hk['text'] = [[('' if not np.isfinite(v) else format(v, fmt)) for v in row] for row in z]
        hk['texttemplate'] = '%{text}'
    if linewidths: hk['xgap'] = hk['ygap'] = float(linewidths)
    fig.add_trace(go.Heatmap(**hk))
    try:
        fig.update_layout(yaxis=dict(autorange='reversed'))   # matrix orientation
        if square: fig.update_layout(yaxis_scaleanchor='x')
    except Exception:
        pass
    return _plt().gca()


# ── regression ──────────────────────────────────────────────────────

def regplot(data=None, *, x=None, y=None, scatter=True, ci=95, order=1,
            color=None, marker='o', label=None, ax=None, **kw):
    go = _go(); fig = _fig()
    x_arr, xl = _resolve(data, x)
    y_arr, yl = _resolve(data, y)
    xa, ya = np.asarray(x_arr, float), np.asarray(y_arr, float)
    m = np.isfinite(xa) & np.isfinite(ya)
    xa, ya = xa[m], ya[m]
    c = _plt()._color_to_str(color) or _plt()._next_color()
    if scatter:
        fig.add_trace(go.Scatter(x=xa.tolist(), y=ya.tolist(), mode='markers',
                                 marker=dict(size=7, color=c), name=(label or 'data'),
                                 showlegend=bool(label)))
    if len(xa) >= 2:
        coeffs = np.polyfit(xa, ya, int(order))
        gx = np.linspace(xa.min(), xa.max(), 100)
        gy = np.polyval(coeffs, gx)
        fig.add_trace(go.Scatter(x=gx.tolist(), y=gy.tolist(), mode='lines',
                                 line=dict(color=c, width=2), name='fit', showlegend=False))
        if ci:   # bootstrap CI band like seaborn
            rng = np.random.RandomState(0)
            boots = np.empty((200, len(gx)))
            n = len(xa)
            for b in range(200):
                idx = rng.randint(0, n, n)
                try:
                    cb = np.polyfit(xa[idx], ya[idx], int(order))
                    boots[b] = np.polyval(cb, gx)
                except Exception:
                    boots[b] = gy
            lo = np.percentile(boots, (100 - ci) / 2, axis=0)
            hi = np.percentile(boots, 100 - (100 - ci) / 2, axis=0)
            fig.add_trace(go.Scatter(x=gx.tolist() + gx[::-1].tolist(),
                                     y=hi.tolist() + lo[::-1].tolist(),
                                     fill='toself', fillcolor='rgba(100,100,200,0.18)',
                                     line=dict(color='rgba(0,0,0,0)'),
                                     hoverinfo='skip', showlegend=False, name='ci'))
    return _finish(xl, yl)


# ── figure-level conveniences ──────────────────────────────────────

def pairplot(data, *, hue=None, vars=None, palette=None, corner=False, **kw):
    """Scatter-matrix approximation of sns.pairplot via go.Splom."""
    go = _go(); fig = _fig()
    import pandas as pd
    cols = vars if vars is not None else [c for c in data.columns
                                          if np.issubdtype(np.asarray(data[c]).dtype, np.number)]
    dims = [dict(label=str(c), values=_plt()._to_list(data[c])) for c in cols]
    mk = dict(size=4)
    if hue is not None:
        levels = list(dict.fromkeys(np.asarray(data[hue]).tolist()))
        colors = _palette_colors(palette, len(levels))
        cmapd = {lv: colors[i % len(colors)] for i, lv in enumerate(levels)}
        mk['color'] = [cmapd[v] for v in np.asarray(data[hue])]
    fig.add_trace(go.Splom(dimensions=dims, marker=mk,
                           diagonal_visible=False, showupperhalf=not corner))
    return _plt().gca()


def jointplot(data=None, *, x=None, y=None, kind='scatter', hue=None,
              color=None, **kw):
    """Joint scatter + marginal histograms (single-axes approximation)."""
    if kind == 'kde':
        ax = kdeplot(data=data, x=x, hue=hue, color=color)
        kdeplot(data=data, x=y, hue=hue, color=color)
        return ax
    return scatterplot(data=data, x=x, y=y, hue=hue, color=color)


def ecdfplot(data=None, *, x=None, hue=None, palette=None, hue_order=None,
             color=None, label=None, ax=None, **kw):
    """Empirical CDF — sorted values vs cumulative proportion."""
    go = _go(); fig = _fig()
    if x is None and data is not None and not hasattr(data, 'columns'):
        x = np.asarray(data); data = None
    x_arr, xl = _resolve(data, x)
    if x_arr is None:
        return _plt().gca()
    groups = list(_groups(data, x_arr, None, hue, hue_order))
    colors = _palette_colors(palette, max(len(groups), 1))
    for i, (lv, ag, _unused) in enumerate(groups):
        v = np.sort(np.asarray(ag, float))
        prop = np.arange(1, len(v) + 1) / len(v)
        c = (_plt()._color_to_str(color) if (color and len(groups) == 1) else colors[i % len(colors)])
        fig.add_trace(go.Scatter(x=v.tolist(), y=prop.tolist(), mode='lines',
                                 line=dict(color=c, shape='hv'),
                                 name=(lv or label or xl or 'ecdf'),
                                 showlegend=bool(lv or label)))
    return _finish(xl, 'Proportion')


def pointplot(data=None, *, x=None, y=None, hue=None, palette=None,
              hue_order=None, estimator='mean', color=None, ax=None, **kw):
    """Category means as connected points (CI bars omitted)."""
    go = _go(); fig = _fig()
    est = {'mean': np.mean, 'median': np.median}.get(estimator, estimator if callable(estimator) else np.mean)
    cl, vl, orient, groups = _cat_groups(data, x, y, hue, hue_order)
    colors = _palette_colors(palette, max(len(groups), 1))
    for i, (lv, cats, vals) in enumerate(groups):
        levels = list(dict.fromkeys(cats.tolist()))
        means = [float(est(np.asarray(vals)[cats == c].astype(float))) for c in levels] \
            if vals is not None else [float(np.sum(cats == c)) for c in levels]
        c = (_plt()._color_to_str(color) if (color and len(groups) == 1) else colors[i % len(colors)])
        fig.add_trace(go.Scatter(
            x=[str(v) for v in levels] if orient == 'v' else means,
            y=means if orient == 'v' else [str(v) for v in levels],
            mode='lines+markers', marker=dict(size=9, color=c), line=dict(color=c),
            name=(lv or vl or ''), showlegend=lv is not None))
    return _finish(cl if orient == 'v' else vl, vl if orient == 'v' else cl)


# ── figure-level wrappers ──────────────────────────────────────────
# Official seaborn returns FacetGrid/JointGrid objects and supports
# col=/row= faceting. The plotly backend draws on a single axes; when
# faceting is requested we flatten (hue still works) and say so once.

def _facet_note(kw, fname):
    if kw.pop('col', None) is not None or kw.pop('row', None) is not None:
        _warn_once(f'{fname}.facet',
                   f"{fname}: col=/row= faceting not supported on iOS — "
                   "drawing all data on one axes (hue still separates groups)")
    for k in ('col_wrap', 'col_order', 'row_order', 'height', 'aspect',
              'facet_kws', 'margin_titles'):
        kw.pop(k, None)
    return kw


def relplot(data=None, *, x=None, y=None, hue=None, kind='scatter', **kw):
    kw = _facet_note(kw, 'relplot')
    fn = lineplot if kind == 'line' else scatterplot
    return fn(data=data, x=x, y=y, hue=hue, **kw)


def displot(data=None, *, x=None, y=None, hue=None, kind='hist', **kw):
    kw = _facet_note(kw, 'displot')
    if kind == 'kde':
        kw.pop('kde', None)
        return kdeplot(data=data, x=x, hue=hue, **kw)
    if kind == 'ecdf':
        return ecdfplot(data=data, x=x, hue=hue, **kw)
    return histplot(data=data, x=x, y=y, hue=hue, **kw)


def catplot(data=None, *, x=None, y=None, hue=None, kind='strip', **kw):
    kw = _facet_note(kw, 'catplot')
    fn = {'strip': stripplot, 'swarm': swarmplot, 'box': boxplot,
          'violin': violinplot, 'bar': barplot, 'count': countplot,
          'point': pointplot}.get(kind)
    if fn is None:
        _warn_once(f'catplot.{kind}', f"catplot: kind={kind!r} not supported — using strip")
        fn = stripplot
    if kind == 'count':
        return fn(data=data, x=x, y=y, hue=hue, **kw)
    return fn(data=data, x=x, y=y, hue=hue, **kw)


def lmplot(data=None, *, x=None, y=None, hue=None, palette=None,
           hue_order=None, ci=95, order=1, **kw):
    kw = _facet_note(kw, 'lmplot')
    if hue is None:
        return regplot(data=data, x=x, y=y, ci=ci, order=order)
    x_arr, _xl = _resolve(data, x)
    y_arr, _yl = _resolve(data, y)
    groups = list(_groups(data, x_arr, y_arr, hue, hue_order))
    colors = _palette_colors(palette, max(len(groups), 1))
    ax = None
    import pandas as pd
    for i, (lv, xg, yg) in enumerate(groups):
        ax = regplot(data=pd.DataFrame({'x': xg, 'y': yg}), x='x', y='y',
                     ci=ci, order=order, color=colors[i % len(colors)], label=lv)
    return ax


def clustermap(data, *, cmap=None, annot=None, **kw):
    _warn_once('clustermap',
               "clustermap: hierarchical clustering/dendrograms not supported "
               "on iOS — drawing the heatmap unclustered")
    for k in ('method', 'metric', 'z_score', 'standard_scale', 'row_cluster',
              'col_cluster', 'row_linkage', 'col_linkage', 'figsize',
              'cbar_pos', 'dendrogram_ratio', 'colors_ratio', 'tree_kws',
              'row_colors', 'col_colors'):
        kw.pop(k, None)
    return heatmap(data, cmap=cmap, annot=annot, **kw)
